INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l27','at the height of','',NULL,'/æt ðə haɪt ʌv/','The king was at the height of his power.','国王正处于权力的顶峰。','The storm struck at the height of the festival.','风暴在节日最热闹时袭来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l27','play a role in','',NULL,'/pleɪ ə roʊl ɪn/','The ship was to play a leading role in the fleet.','这船本要在舰队中担当要角。','Luck plays a role in success.','运气在成功中起一定作用。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l27','in reply','',NULL,'/ɪn rɪˈplaɪ/','The Vasa fired a salute in reply.','瓦萨号鸣炮回礼。','He only nodded in reply.','他只是点头作答。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l27','go down','',NULL,'/ɡoʊ daʊn/','The mighty ship went down in the harbor.','这艘雄伟的船在港湾里沉没了。','The sun went down behind the hills.','太阳落到了山后。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp1','choice','{"stem":"\"The king ___ dictated the ship''s size before work began.\"(过去完成时,比‘开始’更早的过去,填与过去分词搭配的助动词)","options":["had","have","was","has"],"answer_index":0,"stem_cn":"动工之前,国王早已规定了这船的尺寸。","explanation_cn":"过去完成时 had + 过去分词,表比‘开始’更早的过去。✓ had dictated the ship''s size before work began. ✗ has / have(时态)/ was:‘过去的过去’用 had。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp1','choice','{"stem":"\"They ___ laboured for three years before she was launched.\"(过去完成时,填与过去分词搭配的助动词)","options":["did","had","has","have"],"answer_index":1,"stem_cn":"下水之前,他们已辛苦造了三年。","explanation_cn":"过去完成时 had + 过去分词。✓ They had laboured for three years before … ✗ has / have / did:过去完成用 had + 过去分词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp1','choice','{"stem":"\"By 1956 the wreck ___ lain on the seabed for centuries.\"(过去完成时,填与过去分词搭配的助动词)","options":["have","has","was","had"],"answer_index":3,"stem_cn":"到1956年,这艘沉船已在海底躺了几个世纪。","explanation_cn":"过去完成时 had + 过去分词(lain)。✓ the wreck had lain on the seabed for centuries. ✗ has / have / was:过去完成用 had。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp2','choice','{"stem":"\"The Vasa was more richly carved ___ any previous ship.\"(‘比…都’,比较级后接的那个连词)","options":["as","then","than","that"],"answer_index":2,"stem_cn":"瓦萨号比以往任何船都雕饰得更华丽。","explanation_cn":"比较级后接 than,‘比…’。✓ more richly carved than any previous ship. ✗ then(那时)/ as / that:比较用 than。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp2','choice','{"stem":"\"She was more magnificent than ___ other ship in the fleet.\"(‘比其他任何一艘都’,填表‘任何’的词)","options":["some","any","all","none"],"answer_index":1,"stem_cn":"她比舰队里其他任何一艘都更壮观。","explanation_cn":"‘比其他任何一艘都’= than any other + 单数名词;填 any。✓ more magnificent than any other ship. ✗ some / all / none:‘任何’用 any。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp2','choice','{"stem":"\"No ship was ___ splendid than the royal flagship.\"(‘没有比…更…’,比较级表最高级,填 splendid 前那个词)","options":["so","most","very","more"],"answer_index":3,"stem_cn":"没有哪艘船比这皇家旗舰更华丽。","explanation_cn":"‘没有比…更…’,比较级表最高级;splendid 是双音节形容词,前面加 more。✓ No ship was more splendid than … ✗ most(最高级)/ very / so:多音节比较级用 more。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp3','choice','{"stem":"\"The Vasa sank ___ all her flags flying.\"(‘随着…’的独立结构,句中那个介词,与后面名词+现在分词搭配)","options":["in","with","on","at"],"answer_index":1,"stem_cn":"瓦萨号沉没时,所有旗帜仍在飘扬。","explanation_cn":"‘随着/伴随…’的独立结构(with + 名词 + 现在分词),句中那个介词是 with。✓ sank with all her flags flying. ✗ in / on / at:独立结构用 with。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp3','choice','{"stem":"\"She emerged from the smoke, with the water ___ to foam beneath her bow.\"(with + 名词 + 分词的独立结构,被动‘被搅成’,填‘搅动’那个动词的过去分词)","options":["to churn","churning","churned","churn"],"answer_index":2,"stem_cn":"她驶出烟雾,船首下的水被搅成了白沫。","explanation_cn":"with + 名词 + 分词的独立结构;水是‘被搅’,用被动,填‘搅动’那个动词的过去分词 churned。✓ with the water churned to foam. ✗ churning(主动)/ churn / to churn:被动用过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp3','choice','{"stem":"\"The ship listed, with the crew ___ across the deck.\"(with + 名词 + 分词的独立结构,主动‘滑动’,填‘滑’那个动词的现在分词)","options":["sliding","slid","to slide","slide"],"answer_index":0,"stem_cn":"船倾侧了,水手们在甲板上滑向一侧。","explanation_cn":"with + 名词 + 分词的独立结构;水手是‘主动滑动’,填‘滑’那个动词的现在分词 sliding。✓ with the crew sliding across the deck. ✗ slid / slide / to slide:主动进行用现在分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp4','choice','{"stem":"\"As the wind freshened, there ___ a sudden squall.\"(there + 动词 倒装,一般过去时‘来了’,填 come 的过去式)","options":["comes","coming","came","come"],"answer_index":2,"stem_cn":"风势转急,突然来了一阵飑。","explanation_cn":"there + 动词 的全部倒装,一般过去时;填 come 的过去式 came。✓ there came a sudden squall. ✗ come / comes / coming:过去式用 came。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp4','choice','{"stem":"\"There ___ at the bottom of the harbor a mighty warship.\"(there + 动词 倒装,‘躺着’,填 lie 的过去式)","options":["lain","lay","laid","lie"],"answer_index":1,"stem_cn":"港底躺着一艘威武的战舰。","explanation_cn":"there + 动词 的全部倒装,‘躺着’;填 lie(躺)的过去式 lay。✓ There lay a mighty warship. ✗ lie(原形)/ laid(put 的过去式)/ lain(过去分词):lie 的过去式是 lay。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp4','choice','{"stem":"\"There ___ a great cheer as the ship began to move.\"(there + 动词 倒装,‘响起’,填 rise 的过去式)","options":["rose","rising","raise","risen"],"answer_index":0,"stem_cn":"船开始移动时,爆发出一阵欢呼。","explanation_cn":"there + 动词 的全部倒装,‘响起/升起’;填 rise 的过去式 rose。✓ There rose a great cheer. ✗ raise(及物,需宾语)/ risen(过去分词)/ rising:rise 的过去式是 rose。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp5','choice','{"stem":"\"The Vasa was intended ___ play a leading role in the fleet.\"(be intended + 不定式,‘打算用来…’,填不定式符号)","options":["at","to","for","of"],"answer_index":1,"stem_cn":"瓦萨号本打算在舰队中担当要角。","explanation_cn":"be intended + 不定式,‘打算用来做…’;填不定式符号 to。✓ was intended to play a leading role. ✗ for / at / of:不定式用 to。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp5','choice','{"stem":"\"The officer ordered the cannon ___ be heaved across.\"(order sth + 不定式(被动),填不定式符号)","options":["in","for","at","to"],"answer_index":3,"stem_cn":"军官下令把大炮搬向另一侧。","explanation_cn":"order sth + 不定式(此处被动 to be heaved);填不定式符号 to。✓ ordered the cannon to be heaved. ✗ for / at / in:不定式用 to。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp5','choice','{"stem":"\"The king wanted the ship ___ be the finest in Europe.\"(want sth + 不定式,填不定式符号)","options":["for","to","at","of"],"answer_index":1,"stem_cn":"国王想让这船成为全欧洲最好的。","explanation_cn":"want sth + 不定式;填不定式符号 to。✓ wanted the ship to be the finest. ✗ for / at / of:不定式用 to。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp6','choice','{"stem":"\"A large sailing warship of past centuries is a ___.\"(“大帆船”用哪个词)","options":["ferry","raft","canoe","galleon"],"answer_index":3,"stem_cn":"昔日的大型帆船战舰。","explanation_cn":"昔日的大型帆船战舰是 galleon。✓ a large sailing warship is a galleon. ✗ canoe 独木舟;✗ ferry 渡轮;✗ raft 木筏——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp6','choice','{"stem":"\"A sudden violent gust of wind, often with rain, is a ___.\"(“飑,狂风”用哪个词)","options":["squall","breeze","calm","drizzle"],"answer_index":0,"stem_cn":"突然而猛烈、常带雨的一阵风。","explanation_cn":"突然而猛烈、常带雨的一阵风是 squall(飑)。✓ a sudden violent gust is a squall. ✗ breeze 微风;✗ drizzle 毛毛雨;✗ calm 平静——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',5,'am4_l27_gp6','choice','{"stem":"\"The chief ship carrying the commander of a fleet is the ___.\"(“旗舰”用哪个词)","options":["tugboat","flagship","ferry","lifeboat"],"answer_index":1,"stem_cn":"载着舰队司令的主力舰。","explanation_cn":"载着舰队司令的主力舰是 flagship(旗舰)。✓ the ship carrying the commander is the flagship. ✗ lifeboat 救生艇;✗ tugboat 拖船;✗ ferry 渡轮——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',6,NULL,'choice','{"stem":"galleon 的意思是:","options":["木筏","渡轮","独木舟","(大型)帆船"],"answer_index":3,"explanation_cn":"galleon = (大型)帆船。✓ she was a great galleon."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',6,NULL,'choice','{"stem":"armament 的意思是:","options":["燃料","武器装备,军备","食物","服装"],"answer_index":1,"explanation_cn":"armament = 武器装备、军备。✓ her measurements and armament."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',6,NULL,'choice','{"stem":"imperial 的意思是:","options":["地方的","私人的","帝国的,皇帝的","临时的"],"answer_index":2,"explanation_cn":"imperial = 帝国的、皇帝的。✓ Sweden''s imperial fleet."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',6,NULL,'choice','{"stem":"triple 的意思是:","options":["三重的,三倍的","一半的","单一的","双重的"],"answer_index":0,"explanation_cn":"triple = 三重的、三倍的。✓ triple gun-decks."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',6,NULL,'choice','{"stem":"bronze 的意思是:","options":["黄金","铁","白银","青铜"],"answer_index":3,"explanation_cn":"bronze = 青铜。✓ sixty-four bronze cannon."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',6,NULL,'choice','{"stem":"cannon 的意思是:","options":["大炮","盾牌","步枪","箭"],"answer_index":0,"explanation_cn":"cannon = 大炮。✓ the muzzles of her cannon."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',7,NULL,'cloze','{"stem":"第 1 空","context":"The Vasa, the royal flagship, ___1___ been built with triple gun-decks and sixty-four bronze cannon. She was intended ___2___ rule the Baltic. But on her maiden voyage there ___3___ a sudden squall, and she sank ___4___ all her flags flying.","blank_no":1,"options":["had","has","have","was"],"answer_index":0,"explanation_cn":"过去完成时 had + 过去分词(been built)。✓ the Vasa had been built with triple gun-decks."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',7,NULL,'cloze','{"stem":"第 2 空","context":"The Vasa, the royal flagship, ___1___ been built with triple gun-decks and sixty-four bronze cannon. She was intended ___2___ rule the Baltic. But on her maiden voyage there ___3___ a sudden squall, and she sank ___4___ all her flags flying.","blank_no":2,"options":["to","for","at","of"],"answer_index":0,"explanation_cn":"be intended + 不定式;填不定式符号 to。✓ She was intended to rule the Baltic."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',7,NULL,'cloze','{"stem":"第 3 空","context":"The Vasa, the royal flagship, ___1___ been built with triple gun-decks and sixty-four bronze cannon. She was intended ___2___ rule the Baltic. But on her maiden voyage there ___3___ a sudden squall, and she sank ___4___ all her flags flying.","blank_no":3,"options":["came","come","comes","coming"],"answer_index":0,"explanation_cn":"there + 动词 倒装,一般过去时;填 come 的过去式 came。✓ there came a sudden squall."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',7,NULL,'cloze','{"stem":"第 4 空","context":"The Vasa, the royal flagship, ___1___ been built with triple gun-decks and sixty-four bronze cannon. She was intended ___2___ rule the Baltic. But on her maiden voyage there ___3___ a sudden squall, and she sank ___4___ all her flags flying.","blank_no":4,"options":["with","in","on","at"],"answer_index":0,"explanation_cn":"‘随着…’的独立结构,用 with。✓ she sank with all her flags flying."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',8,NULL,'choice','{"stem":"What happened to the Vasa almost immediately after she set sail?","options":["She won a great sea battle","She was captured by an enemy fleet","She sailed safely to another country","A sudden squall made her list, water poured in, and she sank"],"answer_index":3,"explanation_cn":"录音说:瓦萨号刚起航就遇上一阵飑,船身倾侧,海水从敞开的下层炮门灌入,随即沉没。✓ squall, list, water in, sank."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',8,NULL,'choice','{"stem":"Why did water pour into the ship?","options":["A cannon blew a hole in her side","Her lower gun-ports were open and dipped below the waterline as she listed","The crew opened the hatches on purpose","She struck a rock"],"answer_index":1,"explanation_cn":"录音说:船倾侧时,敞开的下层炮门沉到水面以下,海水便灌了进来。✓ open lower gun-ports below water."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',8,NULL,'choice','{"stem":"How long did the Vasa lie at the bottom of the harbor?","options":["For nearly three and a half centuries, until 1956","About ten years","Only a few days","She was never found"],"answer_index":0,"explanation_cn":"录音说:瓦萨号在港底躺了近三个半世纪,直到1956年才被发现。✓ 3.5 centuries until 1956."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',9,NULL,'choice','{"stem":"你想说\"下水之前,他们已辛苦造了三年\"(过去完成时):","options":["They have laboured for three years before she was launched.","They laboured had for three years before she was launched.","They had laboured for three years before she was launched.","They had labour for three years before she was launched."],"answer_index":2,"explanation_cn":"过去完成时 had + 过去分词:had + laboured;用 had(不用 have/has)、后接过去分词 laboured(不写原形 labour)、语序 had 在动词前(不写 laboured had)。✓ They had laboured … 场合:说“(在过去某事之前)早已…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',9,NULL,'choice','{"stem":"你想说\"瓦萨号沉没时,所有旗帜仍在飘扬\"(with 独立结构):","options":["The Vasa sank with all her flags flying.","The Vasa sank with all her flags to fly.","The Vasa sank all her flags flying.","The Vasa sank with all her flags flew."],"answer_index":0,"explanation_cn":"with + 名词 + 现在分词的独立结构:with all her flags flying;旗帜主动飘扬用现在分词 flying(不用过去式 flew、不用 to fly)、且不能省 with。✓ with … flying 场合:补充说明伴随情形。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',9,NULL,'choice','{"stem":"你想说\"风势转急,突然来了一阵飑\"(there + 动词 倒装):","options":["As the wind freshened, came there a sudden squall.","As the wind freshened, there came suddenly a squall it.","As the wind freshened, there come a sudden squall.","As the wind freshened, there came a sudden squall."],"answer_index":3,"explanation_cn":"there + 动词 的全部倒装:there came + 后面那个真正的名词 a squall;come 用过去式 came(不写 come)、语序为 there came(不写 came there)、不加多余的 it。✓ there came a sudden squall. 场合:引出‘出现了…’。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"galleon 的意思是:","options":["木筏","渡轮","(大型)帆船","独木舟"],"answer_index":2,"explanation_cn":"galleon = (大型)帆船。✓ she was a great galleon."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"cannon 的意思是:","options":["步枪","盾牌","箭","大炮"],"answer_index":3,"explanation_cn":"cannon = 大炮。✓ sixty-four bronze cannon."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"\"They ___ laboured for three years before she was launched.\"(过去完成时,填与过去分词搭配的助动词)","options":["did","had","have","has"],"answer_index":1,"stem_cn":"下水之前,他们已辛苦造了三年。","explanation_cn":"过去完成时 had + 过去分词。✓ They had laboured for three years. ✗ has / have / did。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"\"The Vasa sank ___ all her flags flying.\"(‘随着…’的独立结构,填句中那个介词)","options":["on","at","with","in"],"answer_index":2,"stem_cn":"瓦萨号沉没时,旗帜仍在飘扬。","explanation_cn":"‘随着…’的独立结构,用 with。✓ sank with all her flags flying. ✗ in / on / at。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"\"at the height of\" 的意思是:","options":["在…的边缘","在…的底部","在…之后","在…的顶峰/鼎盛期"],"answer_index":3,"explanation_cn":"at the height of = 在…的顶峰、鼎盛期。✓ at the height of his power."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"\"go down\" 的意思是:","options":["转弯","(船)沉没;(日)落下","停止","上升"],"answer_index":1,"explanation_cn":"go down = (船)沉没;(太阳)落下。✓ the ship went down in the harbor."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"Why was the Vasa so richly carved and ornamented?","options":["Carvings made her sail faster","She was a cheap merchant ship","She was the royal flagship, built to display the might of Sweden","The carvings were added after she sank"],"answer_index":2,"passage":"Among the strangest tales of the sea is the story of the Vasa, the royal flagship of seventeenth-century Sweden. She was a great galleon, and King Gustavus Adolphus, known as ''the Northern Hurricane,'' then at the height of his military success in the Thirty Years'' War, had himself dictated her measurements and her armament. Triple gun-decks were to mount sixty-four bronze cannon, and the ship was intended to play a leading role in the growing might of Sweden''s imperial fleet. For three years her builders had laboured to produce a floating work of art, more richly carved and ornamented than any ship before her. Her high stern was a riot of carved figures — kings and warriors, mermaids and strange beasts — bright with red and gold, meant to stir the imagination of all who saw her. On the tenth of August, 1628, the day of her maiden voyage, Stockholm was in a ferment. From the quays and the surrounding islands the people watched this thing of beauty spread her sails and catch the wind. The anchored warships thundered a salute, to which the Vasa fired a proud reply, and as she emerged from her drifting cloud of gun-smoke, with the water churned to foam beneath her bow, she made a more majestic spectacle than the citizens had ever seen. All her gun-ports stood open, and the muzzles of her cannon showed through them. Then, as the wind freshened, there came a sudden squall. The great ship made a strange movement and began to list to one side, her ballast shifting with her. The officer in charge ordered the cannon to be heaved across to right her, but the angle of the decks only steepened. The lower gun-ports, still open, dipped below the surface, and the sea poured in. In that first glorious hour, the mighty Vasa, which had been built to rule the Baltic, went down in the harbor of her birth, her flags still flying. There she lay on the seabed for nearly three and a half centuries, until her discovery in 1956 restored her to the world.","explanation_cn":"课文说:瓦萨号是皇家旗舰,雕饰华丽是为了彰显瑞典日渐壮大的国力。✓ royal flagship, display might."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"What caused the Vasa to sink on her maiden voyage?","options":["A squall made her list until water poured through her open lower gun-ports","She hit another ship","An enemy cannon sank her","She caught fire"],"answer_index":0,"passage":"Among the strangest tales of the sea is the story of the Vasa, the royal flagship of seventeenth-century Sweden. She was a great galleon, and King Gustavus Adolphus, known as ''the Northern Hurricane,'' then at the height of his military success in the Thirty Years'' War, had himself dictated her measurements and her armament. Triple gun-decks were to mount sixty-four bronze cannon, and the ship was intended to play a leading role in the growing might of Sweden''s imperial fleet. For three years her builders had laboured to produce a floating work of art, more richly carved and ornamented than any ship before her. Her high stern was a riot of carved figures — kings and warriors, mermaids and strange beasts — bright with red and gold, meant to stir the imagination of all who saw her. On the tenth of August, 1628, the day of her maiden voyage, Stockholm was in a ferment. From the quays and the surrounding islands the people watched this thing of beauty spread her sails and catch the wind. The anchored warships thundered a salute, to which the Vasa fired a proud reply, and as she emerged from her drifting cloud of gun-smoke, with the water churned to foam beneath her bow, she made a more majestic spectacle than the citizens had ever seen. All her gun-ports stood open, and the muzzles of her cannon showed through them. Then, as the wind freshened, there came a sudden squall. The great ship made a strange movement and began to list to one side, her ballast shifting with her. The officer in charge ordered the cannon to be heaved across to right her, but the angle of the decks only steepened. The lower gun-ports, still open, dipped below the surface, and the sea poured in. In that first glorious hour, the mighty Vasa, which had been built to rule the Baltic, went down in the harbor of her birth, her flags still flying. There she lay on the seabed for nearly three and a half centuries, until her discovery in 1956 restored her to the world.","explanation_cn":"课文说:一阵飑使她倾侧,海水从敞开的下层炮门灌入,导致沉没。✓ squall, list, open gun-ports."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"When was the Vasa rediscovered?","options":["In the nineteenth century","In 1956, after nearly three and a half centuries","She has never been found","In 1628, the same year she sank"],"answer_index":1,"audio":"Among the strangest tales of the sea is the story of the Vasa, the royal flagship of seventeenth-century Sweden. She was a great galleon, and King Gustavus Adolphus, known as ''the Northern Hurricane,'' then at the height of his military success in the Thirty Years'' War, had himself dictated her measurements and her armament. Triple gun-decks were to mount sixty-four bronze cannon, and the ship was intended to play a leading role in the growing might of Sweden''s imperial fleet. For three years her builders had laboured to produce a floating work of art, more richly carved and ornamented than any ship before her. Her high stern was a riot of carved figures — kings and warriors, mermaids and strange beasts — bright with red and gold, meant to stir the imagination of all who saw her. On the tenth of August, 1628, the day of her maiden voyage, Stockholm was in a ferment. From the quays and the surrounding islands the people watched this thing of beauty spread her sails and catch the wind. The anchored warships thundered a salute, to which the Vasa fired a proud reply, and as she emerged from her drifting cloud of gun-smoke, with the water churned to foam beneath her bow, she made a more majestic spectacle than the citizens had ever seen. All her gun-ports stood open, and the muzzles of her cannon showed through them. Then, as the wind freshened, there came a sudden squall. The great ship made a strange movement and began to list to one side, her ballast shifting with her. The officer in charge ordered the cannon to be heaved across to right her, but the angle of the decks only steepened. The lower gun-ports, still open, dipped below the surface, and the sea poured in. In that first glorious hour, the mighty Vasa, which had been built to rule the Baltic, went down in the harbor of her birth, her flags still flying. There she lay on the seabed for nearly three and a half centuries, until her discovery in 1956 restored her to the world.","explanation_cn":"课文说:瓦萨号沉没后在海底躺了近三个半世纪,1956年才被发现。✓ rediscovered 1956."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l27',10,NULL,'choice','{"stem":"What kind of ship was the Vasa?","options":["A small fishing boat","A wooden raft","A royal galleon and flagship with triple gun-decks","A modern steamship"],"answer_index":2,"audio":"Among the strangest tales of the sea is the story of the Vasa, the royal flagship of seventeenth-century Sweden. She was a great galleon, and King Gustavus Adolphus, known as ''the Northern Hurricane,'' then at the height of his military success in the Thirty Years'' War, had himself dictated her measurements and her armament. Triple gun-decks were to mount sixty-four bronze cannon, and the ship was intended to play a leading role in the growing might of Sweden''s imperial fleet. For three years her builders had laboured to produce a floating work of art, more richly carved and ornamented than any ship before her. Her high stern was a riot of carved figures — kings and warriors, mermaids and strange beasts — bright with red and gold, meant to stir the imagination of all who saw her. On the tenth of August, 1628, the day of her maiden voyage, Stockholm was in a ferment. From the quays and the surrounding islands the people watched this thing of beauty spread her sails and catch the wind. The anchored warships thundered a salute, to which the Vasa fired a proud reply, and as she emerged from her drifting cloud of gun-smoke, with the water churned to foam beneath her bow, she made a more majestic spectacle than the citizens had ever seen. All her gun-ports stood open, and the muzzles of her cannon showed through them. Then, as the wind freshened, there came a sudden squall. The great ship made a strange movement and began to list to one side, her ballast shifting with her. The officer in charge ordered the cannon to be heaved across to right her, but the angle of the decks only steepened. The lower gun-ports, still open, dipped below the surface, and the sea poured in. In that first glorious hour, the mighty Vasa, which had been built to rule the Baltic, went down in the harbor of her birth, her flags still flying. There she lay on the seabed for nearly three and a half centuries, until her discovery in 1956 restored her to the world.","explanation_cn":"课文说:瓦萨号是一艘皇家大帆船兼旗舰,配三层炮甲板、六十四门青铜炮。✓ royal galleon, flagship, triple decks."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
